from typing import List, Tuple
class Node:
    def __init__(self, start: int, end: int):
        self.start = start
        self.end = end
        self.left = None
        self.right = None
        self.plus = 0  # the value added to each interval
        self.total = 0  # the total value in each interval

def insert(node: Node, start: int, end: int, val: int) -> None:
    if node.start == start and node.end == end:
        node.plus += val
        node.total += val
        return None
    mid = (node.start + node.end) // 2
    if start <= mid:
        if not node.left:
            node.left = Node(node.start, mid)
        if end <= mid:
            insert(node.left, start, end, val)
            node.total = node.left.total + node.right.total if node.right else node.left.total
        else:
            insert(node.left, start, mid, val)
            insert(node.right, mid + 1, end, val)
            node.total = node.left.total + node.right.total
    else:
        if not node.right:
            node.right = Node(mid + 1, node.end)
        insert(node.right, start, end, val)
        node.total = node.left.total + node.right.total if node.left else node.right.total
    node.total += node.plus

def dfs(node: Node, index: int, result: List[int]) -> None:
    if node:
        if node.start == node.end:
            result[node.start] = node.total
        else:
            mid = (node.start + node.end) // 2
            if index <= mid and node.left:
                result[index] = node.total if node.left.total <= 0 else node.left.total
            elif index > mid and node.right:
                result[index] = node.total if node.right.total <= 0 else node.right.total
            if index <= mid:
                dfs(node.left, index, result)
            else:
                dfs(node.right, index, result)

